query FeedRender($first: Int!, $after: String) {
  feed(first: $first, after: $after) {
    edges {
      cursor
      node {
        ...FeedItemFields
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

fragment AuthorFields on User {
  id
  name
  avatarUrl
}

fragment CommentFields on Comment {
  id
  text
  author {
    ...AuthorFields
  }
}

fragment CommentListFields on Post {
  comments(first: 10) {
    edges {
      node {
        ...CommentFields
      }
    }
  }
}

fragment FeedItemFields on Post {
  id
  text
  createdAt
  likeCount
  author {
    ...AuthorFields
  }
  ...CommentListFields
}
